mapper.select:
SELECT t.id, t.title, t.detail, c.name AS category, t.priority, t.due_date, t.completed,
       CASE WHEN t.completed = TRUE THEN 'COMPLETED' ELSE t.status END AS status,
       t.created_at, t.updated_at, COALESCE(a.attachment_count, 0) AS attachment_count
FROM todos t
JOIN todo_categories c ON c.id = t.category_id
LEFT JOIN (
    SELECT todo_id, COUNT(*) AS attachment_count
    FROM todo_attachments
    GROUP BY todo_id
) a ON a.todo_id = t.id


        AND t.title LIKE CONCAT('%', #{keyword}, '%')


        AND c.name = #{category}


        AND t.due_date >= #{from}


        AND t.due_date <= #{to}


ORDER BY t.due_date ${order}
